-- Exact release probe: synthetic metadata is confined to this rolled-back transaction.
begin;
create extension if not exists pgtap with schema extensions;
set local search_path=public,extensions;
select no_plan();
create function pg_temp.prove(result text)returns void language plpgsql as $$begin
 if result not like 'ok %'then raise exception 'Hosted inventory identity proof failed: %',result;end if;
 perform set_config('lrv.identity_checks',(coalesce(nullif(current_setting('lrv.identity_checks',true),''),'0')::integer+1)::text,true);
end $$;
create temp table identity_fixture(key text primary key,value jsonb);
grant all on identity_fixture to authenticated;
insert into identity_fixture select key,to_jsonb(gen_random_uuid())from unnest(array['actor','session','namespace','package','product','namespace_action','package_action','missing_action'])key;
create function pg_temp.id(key text)returns uuid language sql as $$select(value#>>'{}')::uuid from identity_fixture where identity_fixture.key=$1$$;
insert into identity_fixture values('baseline',jsonb_build_object('stock',(select count(*)from inventory_movements),'outbox',(select count(*)from communication_outbox),'invoices',(select count(*)from billing_invoices)));
insert into auth.users(id,email,raw_user_meta_data)values(pg_temp.id('actor'),'synthetic-identity-'||pg_temp.id('actor')||'@example.test','{}');
update profiles set is_active=true,full_name='Synthetic rollback inventory reviewer'where id=pg_temp.id('actor');
insert into user_roles(user_id,role)values(pg_temp.id('actor'),'DVM')on conflict do nothing;
insert into auth.sessions(id,user_id,created_at,updated_at)values(pg_temp.id('session'),pg_temp.id('actor'),now(),now());
select pg_temp.prove(ok(relrowsecurity and not has_table_privilege('anon',oid,'SELECT')and not has_table_privilege('authenticated',oid,'SELECT')and not has_table_privilege('service_role',oid,'INSERT'),relname||' private RLS'))from pg_class where relnamespace='public'::regnamespace and relname in('inventory_identity_entries','inventory_identity_versions','inventory_identity_bindings','inventory_identity_reviews','inventory_identity_actions','inventory_identity_cancellations');
select pg_temp.prove(ok(not has_function_privilege('anon',oid,'EXECUTE')and not has_function_privilege('service_role',oid,'EXECUTE')and has_function_privilege('authenticated',oid,'EXECUTE'),proname||' guarded RPC'))from pg_proc where pronamespace='public'::regnamespace and proname in('prepare_inventory_identity_review','execute_inventory_identity_review','read_inventory_identity_review','cancel_inventory_identity_review','list_inventory_identities','read_inventory_identity','lookup_inventory_identifier');
select pg_temp.prove(ok(not exists(select 1 from pg_proc where pronamespace='public'::regnamespace and proname like 'inventory_identity_%'and(has_function_privilege('authenticated',oid,'EXECUTE')or has_function_privilege('service_role',oid,'EXECUTE'))),'All private helpers remain owner only'));
select pg_temp.prove(is(inventory_identity_gtin('036000291452'),'00036000291452','Manufacturer GTIN normalized exactly'));
select pg_temp.prove(throws_ok($q$select inventory_identity_gtin('036000291453')$q$,'23514',null,'Invalid check digit rejected'));
select set_config('request.jwt.claims',jsonb_build_object('role','authenticated','sub',pg_temp.id('actor'),'session_id',pg_temp.id('session'))::text,true);
set local role authenticated;
select create_inventory_product(pg_temp.id('product'),'Synthetic rollback vial','medication','Synthetic maker','mL',100);
insert into identity_fixture values('namespace_request',jsonb_build_object('id',pg_temp.id('namespace'),'expected_version',null,'definition',jsonb_build_object('supplier','mwi','account_label','Synthetic rollback '||pg_temp.id('namespace'),'catalog_scope','Rollback only','active',true),'review_note','Synthetic rollback-only supplier metadata review','attest_review',true));
select pg_temp.prove(is(prepare_inventory_identity_review(pg_temp.id('actor'),pg_temp.id('namespace_action'),'namespace',(select value from identity_fixture where key='namespace_request'))->>'state','prepared','Exact original namespace preparation'));
insert into identity_fixture values('namespace_saved',execute_inventory_identity_review(pg_temp.id('actor'),pg_temp.id('namespace_action')));
select pg_temp.prove(is(execute_inventory_identity_review(pg_temp.id('actor'),pg_temp.id('namespace_action')),(select value from identity_fixture where key='namespace_saved'),'Same UUID replays original namespace receipt'));
insert into identity_fixture values('package_request',jsonb_build_object('id',pg_temp.id('package'),'expected_version',null,'definition',jsonb_build_object('product_id',pg_temp.id('product'),'product_version',1,'stock_unit','mL','label','Synthetic ten mL vial','manufacturer','Synthetic maker','strength','10mg/mL','form','injectable','purchase_unit','vial','conversion',jsonb_build_object('stock_units_numerator','10','purchase_units_denominator','1'),'identifiers',jsonb_build_array(jsonb_build_object('kind','supplier_sku','namespace_id',pg_temp.id('namespace'),'namespace_version_id',(select value#>>'{entry,version_id}'from identity_fixture where key='namespace_saved'),'value','000123','raw_source','000123')),'active',true),'review_note','Synthetic rollback-only product package review','attest_review',true));
select pg_temp.prove(is(prepare_inventory_identity_review(pg_temp.id('actor'),pg_temp.id('package_action'),'package',(select value from identity_fixture where key='package_request'))->>'state','prepared','Exact original package preparation'));
insert into identity_fixture values('package_saved',execute_inventory_identity_review(pg_temp.id('actor'),pg_temp.id('package_action')));
select pg_temp.prove(is(execute_inventory_identity_review(pg_temp.id('actor'),pg_temp.id('package_action')),(select value from identity_fixture where key='package_saved'),'Same package UUID returns original receipt'));
select pg_temp.prove(is(read_inventory_identity_review(pg_temp.id('actor'),pg_temp.id('package_action'))->'receipt',(select value from identity_fixture where key='package_saved'),'Read-only recovery exact original receipt'));
select pg_temp.prove(is(lookup_inventory_identifier('supplier_sku','000123',pg_temp.id('namespace'))->'items'->0->>'id',pg_temp.id('package')::text,'Leading-zero scoped SKU resolves reviewed package'));
select pg_temp.prove(is(jsonb_array_length(lookup_inventory_identifier('supplier_sku','000124',pg_temp.id('namespace'))->'items'),0,'Unknown SKU creates nothing'));
select pg_temp.prove(is(read_inventory_identity(pg_temp.id('package'))->'entry',(select value->'entry'from identity_fixture where key='package_saved'),'Current mapping equals reviewed immutable evidence'));
select pg_temp.prove(throws_ok($q$select prepare_inventory_identity_review(pg_temp.id('actor'),pg_temp.id('package_action'),'package',(select jsonb_set(value,'{review_note}','"Changed original review"')from identity_fixture where key='package_request'))$q$,'23505',null,'Changed original UUID request rejected'));
select pg_temp.prove(is(cancel_inventory_identity_review(pg_temp.id('actor'),pg_temp.id('package_action'))->'receipt',(select value from identity_fixture where key='package_saved'),'Cancellation cannot erase saved work'));
select pg_temp.prove(is(cancel_inventory_identity_review(pg_temp.id('actor'),pg_temp.id('missing_action'))->>'cancelled','true','Missing original preparation closes safely'));
select pg_temp.prove(is(read_inventory_identity_review(pg_temp.id('actor'),pg_temp.id('missing_action'))->>'state','cancelled','Missing preparation tombstone recovers read only'));
set local timezone='America/Denver';
select pg_temp.prove(is(read_inventory_identity(pg_temp.id('package'))->'entry',(select value->'entry'from identity_fixture where key='package_saved'),'Original receipt is caller-timezone invariant'));
reset role;
select pg_temp.prove(is((select count(*)from inventory_identity_versions where entry_id=pg_temp.id('package')),1::bigint,'Exactly one saved package version'));
select pg_temp.prove(is(jsonb_build_object('stock',(select count(*)from inventory_movements),'outbox',(select count(*)from communication_outbox),'invoices',(select count(*)from billing_invoices)),(select value from identity_fixture where key='baseline'),'Stock billing and communications unchanged'));
set constraints all immediate;
select jsonb_build_object('checks',current_setting('lrv.identity_checks')::integer,'provider_requests',0,'rollback_only',true)as proof;
rollback;
